// src/cli/renderers/cursor-limits-core.js
// cursor-limits.json's text: the library version, every constant the cursor
// section judged with (value and meaning), and the realised sampling
// interval across the cohort, so a report regenerated by a later CLI shows
// which constants adjudicated it. No fs access: report-core.js sinks it.

import { CURSOR_LIMITS } from '../analyzers/cursor.js';

function median(values) {
  if (!values.length) return null;
  const s = values.slice().sort((a, b) => a - b);
  const mid = s.length >> 1;
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

export function buildCursorLimitsJson(libraryVersion, results) {
  const intervals = results.map(r => r.cursor && r.cursor.sampleIntervalMs).filter(v => typeof v === 'number');
  const checkable = results.filter(r => r.checksRecorded > 0).length;
  return JSON.stringify({
    libraryVersion,
    limits: CURSOR_LIMITS,
    sampleIntervalMs: { core: { median: median(intervals), n: intervals.length } },
    sessions: { total: results.length, checkable }
  }, null, 2) + '\n';
}
